InstructionDefinition.Payload:
// get office version installed on the client device i:e office 16, office xx etc
@getOffice          = "Select Name from SoftwareLicensingProduct where Name like '%Office%'";
@storeOfficeVersion = NativeServices.RunWmiQuery(Namespace:"root\\cimv2", Query:@getOffice);
@applicationName    = SELECT REGEXPCAPTURE("Office ..", Name) AS Application FROM @storeOfficeVersion LIMIT 1;

// Getting only numeric value version 
@extractVersion = FOREACH @an IN @applicationName 
    DO 
        SELECT REGEXPCAPTURE('\d{1,}', @an.Application) AS Capture from @an WHERE @an.Application IS NOT NULL;
    DONE;

// Check the version is equal to or greater than 15
@check = SELECT Capture FROM @extractVersion WHERE Capture == 16;

// Stop the execution if Office Package is Not Installed
IF NOT(@check)
    @results = SELECT "Unable to get Outlook version or Version is Not 16" as Data, 0 as Passed;
    RETURN @results;
ENDIF;

@preventAddExitsPST= SELECT 'Software\\Microsoft\\Office\\' ||  Capture  || '.0\\Outlook\\PST' as key from @extractVersion;
@getPSTKey=NativeServices.RegistryKeyExists(Hive:"HKCU", Subkey:@preventAddExitsPST.key);

@checkPSTKey=SELECT @getPSTKey.[Exists] FROM @getPSTKey where @getPSTKey.[Exists]==0;
IF (@checkPSTKey)
    // Concatenate path with version capture for registry key 
    @getKeyAndValue = NativeServices.RegistrySetValue(Hive:"HKCU", Subkey:@preventAddExitsPST.key, Name:"PSTDisableGrow", ValueType:"REG_DWORD", Value:"1");
    SELECT "Created key(PSTDisableGrow) and set value to 1" as Data, 1 as Passed;
ELSE
    // get value of getPSTDisableGrow
    @getPSTDisableGrow = NativeServices.RegistryGetValue(Hive:"HKCU", Subkey:@preventAddExitsPST.key, Name:"PSTDisableGrow");
    @checkPSTDisableGrow = SELECT Value from @getPSTDisableGrow where value==1;
    IF (@checkPSTDisableGrow)
        @showResult = SELECT "PSTDisableGrow is already set to 1" as Data, 1 as Passed;
        RETURN @showResult;
    ELSE
        NativeServices.RegistrySetValue(Hive:"HKCU", Subkey:@preventAddExitsPST.key, Name:"PSTDisableGrow", ValueType:"REG_DWORD", Value:"1");   
        @showResult = SELECT "PSTDisableGrow is set to 1" as Data, 1 as Passed;
        RETURN @showResult;
    ENDIF;
ENDIF;
